//! VHDL-2008 of the machines the programmable logic computes: one clocked
//! entity per machine (`<model>_<machine>`), its Wishbone wrapper
//! (`<model>_<machine>_wb`, the registers of `regmap`) and the package of
//! the fixed-point arithmetic (`arclang_fx_pkg`). numeric_std only, no
//! vendor primitive, synchronous reset; the same model gives the same bytes.
//!
//! The entity does what the C's `step()` does, as `cgen` writes it and with
//! the arithmetic of `fxc`: on `step`, it latches its inputs and runs the
//! step in phases, one per clock — the initial states (first step), each
//! equation, each event of the queue, each timed trigger and the
//! completion transitions, the `do` activities and the time in state — and
//! pulses `done` with the outputs of the step. `ready` is high while it
//! waits for a step. Every state, transition and pseudo-state is the C's
//! (the tables of `execution::Machine`), the procedures of one process.

use super::fixed::{Kind, Loc, MachineFixed, Node, Op, Stmt};
use super::plan::{Guard, MachinePlan, Plan, Trigger};
use super::regmap::{Map, Reg, QUEUE};
use crate::compiler::execution::machine::{Alternative, EntryOp, Next, Segment};
use crate::compiler::execution::expr::{Bin, BlockKind, Fun};
use std::fmt::Write as _;

const RESERVED: [&str; 40] = [
    "abs", "access", "after", "alias", "all", "and", "architecture", "array", "begin", "block", "body", "buffer", "case", "component", "constant", "else", "elsif", "end", "entity", "exit", "file", "for", "function", "if", "in", "is", "label", "loop", "map", "next", "not", "null", "of", "or", "out", "port", "process", "range", "signal", "type",
];

/// A VHDL identifier from a C one: no double, leading or trailing underscore, no reserved word.
pub fn name(c: &str) -> String {
    let mut out = String::new();
    for ch in c.chars() {
        if ch == '_' && (out.is_empty() || out.ends_with('_')) {
            continue;
        }
        out.push(ch.to_ascii_lowercase());
    }
    let out = out.trim_end_matches('_').to_string();
    let out = if out.is_empty() || out.starts_with(|c: char| c.is_ascii_digit()) { format!("x_{out}") } else { out };
    if RESERVED.contains(&out.as_str()) || matches!(out.as_str(), "with" | "while" | "wait" | "when" | "until" | "use" | "units" | "to" | "then" | "subtype" | "select" | "return" | "report" | "register" | "record" | "rem" | "mod" | "new" | "nor" | "nand" | "xor" | "xnor" | "on" | "open" | "others" | "package" | "procedure" | "pure" | "impure" | "shared" | "variable" | "library" | "linkage" | "bus" | "configuration" | "disconnect" | "downto" | "generate" | "generic" | "group" | "guarded" | "inertial" | "inout" | "literal" | "postponed" | "reject" | "transport" | "sla" | "sll" | "sra" | "srl" | "rol" | "ror" | "assert" | "attribute" | "begin" | "clk" | "rst" | "step" | "ready" | "done" | "cycles") {
        format!("{out}_x")
    } else {
        out
    }
}

pub fn entity(plan: &Plan, m: &MachinePlan) -> String {
    name(&format!("{}_{}", plan.ident, m.ident))
}

fn comment(text: &str) -> String {
    text.replace(['\n', '\r'], " ")
}

fn banner(plan: &Plan, what: &str) -> String {
    format!("-- {what}\n-- Generated by ArcLang from model \"{}\". Do not edit: regenerate.\n-- VHDL-2008, numeric_std, synthesisable, no vendor primitive. See docs/embedded-fpga.md.\n", comment(&plan.model))
}

/// The package of the fixed-point arithmetic: the C reference's helpers, bit for bit.
pub const PACKAGE: &str = r#"-- The fixed-point arithmetic of ArcLang's hardware (docs/embedded-fpga.md):
-- the helpers of the C reference (fxc), bit for bit. A word is a signed
-- 32-bit value of its own binary point; rounding is to nearest, ties toward
-- plus infinity; every result saturates to 32 bits; integers saturate.
-- Generated by ArcLang. Do not edit: regenerate.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

package arclang_fx_pkg is
  subtype w32 is signed(31 downto 0);
  subtype w64 is signed(63 downto 0);
  subtype count8 is unsigned(7 downto 0);
  type bool_array is array (natural range <>) of boolean;
  type u32_array is array (natural range <>) of unsigned(31 downto 0);
  type nat_array is array (natural range <>) of natural;
  function fx_rshr(x : w64; n : integer) return w64;
  function fx_align(a : w32; s : integer) return w64;
  function fx_resize(x : w64; d : integer) return w32;
  function fx_min(a, b : w64) return w64;
  function fx_max(a, b : w64) return w64;
  function fx_clamp(x, lo, hi : w64) return w64;
  function fx_sel(c : boolean; a, b : w32) return w32;
  function sat_i64(x : w64) return w32;
  function add_i32(a, b : w32) return w32;
  function sub_i32(a, b : w32) return w32;
  function mul_i32(a, b : w32) return w32;
  function div_i32(a, b : w32) return w32;
  function neg_i32(a : w32) return w32;
  function abs_i32(a : w32) return w32;
  function min_i32(a, b : w32) return w32;
  function max_i32(a, b : w32) return w32;
  function saturate_i32(x, lo, hi : w32) return w32;
  function counted(n : count8) return count8;
  function b2l(b : boolean) return std_logic;
end package;

package body arclang_fx_pkg is
  -- (x + 2^(n-1)) >> n, arithmetic; 0 for a shift of 63 or more.
  function fx_rshr(x : w64; n : integer) return w64 is
  begin
    if n <= 0 then
      return x;
    elsif n >= 63 then
      return to_signed(0, 64);
    else
      return shift_right(x + shift_left(to_signed(1, 64), n - 1), n);
    end if;
  end function;

  -- An operand aligned: s > 0 left (exact, s <= 30), s < 0 rounding right.
  function fx_align(a : w32; s : integer) return w64 is
  begin
    if s >= 0 then
      return shift_left(resize(a, 64), s);
    else
      return fx_rshr(resize(a, 64), -s);
    end if;
  end function;

  function sat_i64(x : w64) return w32 is
  begin
    if x > resize(to_signed(2147483647, 32), 64) then
      return to_signed(2147483647, 32);
    elsif x < resize(signed'(x"80000000"), 64) then
      return signed'(x"80000000");
    else
      return resize(x, 32);
    end if;
  end function;

  -- A result into a word: d > 0 rounding right, d < 0 saturating left; saturated.
  function fx_resize(x : w64; d : integer) return w32 is
    variable l : integer;
  begin
    if d >= 0 then
      return sat_i64(fx_rshr(x, d));
    end if;
    l := -d;
    if l >= 32 then
      if x > 0 then
        return to_signed(2147483647, 32);
      elsif x < 0 then
        return signed'(x"80000000");
      else
        return to_signed(0, 32);
      end if;
    elsif x > shift_left(to_signed(1, 64), 31 - l) - 1 then
      return to_signed(2147483647, 32);
    elsif x < -shift_left(to_signed(1, 64), 31 - l) then
      return signed'(x"80000000");
    else
      return resize(shift_left(x, l), 32);
    end if;
  end function;

  function fx_min(a, b : w64) return w64 is
  begin
    if a < b then return a; else return b; end if;
  end function;

  function fx_max(a, b : w64) return w64 is
  begin
    if a > b then return a; else return b; end if;
  end function;

  function fx_clamp(x, lo, hi : w64) return w64 is
  begin
    if x < lo then
      return lo;
    elsif x > hi then
      return hi;
    else
      return x;
    end if;
  end function;

  function fx_sel(c : boolean; a, b : w32) return w32 is
  begin
    if c then return a; else return b; end if;
  end function;

  function add_i32(a, b : w32) return w32 is
  begin
    return sat_i64(resize(a, 64) + resize(b, 64));
  end function;

  function sub_i32(a, b : w32) return w32 is
  begin
    return sat_i64(resize(a, 64) - resize(b, 64));
  end function;

  function mul_i32(a, b : w32) return w32 is
  begin
    return sat_i64(resize(a * b, 64));
  end function;

  -- Truncated toward zero; a division by zero gives 0.
  function div_i32(a, b : w32) return w32 is
  begin
    if b = 0 then
      return to_signed(0, 32);
    end if;
    return sat_i64(resize(a, 64) / resize(b, 64));
  end function;

  function neg_i32(a : w32) return w32 is
  begin
    return sat_i64(-resize(a, 64));
  end function;

  function abs_i32(a : w32) return w32 is
  begin
    return sat_i64(abs(resize(a, 64)));
  end function;

  function min_i32(a, b : w32) return w32 is
  begin
    if a < b then return a; else return b; end if;
  end function;

  function max_i32(a, b : w32) return w32 is
  begin
    if a > b then return a; else return b; end if;
  end function;

  function saturate_i32(x, lo, hi : w32) return w32 is
  begin
    if x < lo then
      return lo;
    elsif x > hi then
      return hi;
    else
      return x;
    end if;
  end function;

  function counted(n : count8) return count8 is
  begin
    if n < 255 then return n + 1; else return n; end if;
  end function;

  function b2l(b : boolean) return std_logic is
  begin
    if b then return '1'; else return '0'; end if;
  end function;
end package body;
"#;

fn vtype(kind: Kind) -> &'static str {
    match kind {
        Kind::Bool => "boolean",
        _ => "w32",
    }
}

fn word(raw: i64) -> String {
    format!("signed'(x\"{:08X}\")", raw as i32 as u32)
}

fn lit(kind: Kind, raw: i64) -> String {
    match kind {
        Kind::Bool => if raw != 0 { "true" } else { "false" }.to_string(),
        _ => word(raw),
    }
}

/// The names the process gives a machine's values.
struct V<'a> {
    m: &'a MachinePlan,
    fx: &'a MachineFixed,
    ticks: Box<dyn Fn(u64) -> u64 + 'a>,
}

impl V<'_> {
    fn var(&self, i: usize) -> String {
        format!("r_{}", name(&self.m.variables[i].ident))
    }

    fn loc(&self, l: &Loc) -> String {
        match l {
            Loc::Var(i) => self.var(*i),
            Loc::Blk(b, field) => format!("blk{b}_{}", field.name()),
            Loc::Tmp(b, n) => format!("b{b}_{n}"),
        }
    }

    fn act(&self, a: usize) -> String {
        format!("n_{}", name(&self.m.actions[a].ident))
    }

    fn cond(&self, c: usize) -> String {
        format!("l_{}", name(&self.m.conditions[c].ident))
    }

    fn expr(&self, n: &Node) -> String {
        let e = |n: &Node| self.expr(n);
        let al = |n: &Node, s: i32| format!("fx_align({}, {s})", self.expr(n));
        match &n.op {
            Op::Lit(raw) => lit(n.kind, *raw),
            Op::Read(l) => self.loc(l),
            Op::Add { sub, a, b, sa, sb, d } => format!("fx_resize({} {} {}, {d})", al(a, *sa), if *sub { "-" } else { "+" }, al(b, *sb)),
            Op::Mul { a, b, d } => format!("fx_resize({} * {}, {d})", e(a), e(b)),
            Op::Neg { a, d } => format!("fx_resize(-resize({}, 64), {d})", e(a)),
            Op::Abs { a, d } => format!("fx_resize(abs(resize({}, 64)), {d})", e(a)),
            Op::MinMax { max, a, b, sa, sb, d } => format!("fx_resize({}({}, {}), {d})", if *max { "fx_max" } else { "fx_min" }, al(a, *sa), al(b, *sb)),
            Op::Sat { x, lo, hi, s, d } => format!("fx_resize(fx_clamp({}, {}, {}), {d})", al(x, s[0]), al(lo, s[1]), al(hi, s[2])),
            Op::Resize { a, d } => format!("fx_resize(resize({}, 64), {d})", e(a)),
            Op::Cmp { op, a, b, sa, sb } => format!("({} {} {})", al(a, *sa), symbol(*op), al(b, *sb)),
            Op::IntBin { op, a, b } => {
                let f = match op {
                    Bin::Add => "add_i32",
                    Bin::Sub => "sub_i32",
                    Bin::Mul => "mul_i32",
                    _ => "div_i32",
                };
                format!("{f}({}, {})", e(a), e(b))
            }
            Op::IntNeg(a) => format!("neg_i32({})", e(a)),
            Op::IntCall { fun, args } => {
                let f = match fun {
                    Fun::Min => "min_i32",
                    Fun::Max => "max_i32",
                    Fun::Abs => "abs_i32",
                    Fun::Saturate => "saturate_i32",
                };
                format!("{f}({})", args.iter().map(e).collect::<Vec<_>>().join(", "))
            }
            Op::IntCmp { op, a, b } => format!("({} {} {})", e(a), symbol(*op), e(b)),
            Op::Not(a) => format!("(not {})", e(a)),
            Op::Logic { and, a, b } => format!("({} {} {})", e(a), if *and { "and" } else { "or" }, e(b)),
            Op::BoolEq { eq, a, b } => format!("({} {} {})", e(a), if *eq { "=" } else { "/=" }, e(b)),
            Op::Select { c, a, b } => format!("fx_sel({}, {}, {})", e(c), e(a), e(b)),
        }
    }

    fn stmts(&self, code: &[Stmt], indent: &str, out: &mut String) {
        for s in code {
            match s {
                Stmt::Set(l, n) => {
                    let _ = writeln!(out, "{indent}{} := {};", self.loc(l), self.expr(n));
                }
                Stmt::If(c, a, b) => {
                    let _ = writeln!(out, "{indent}if {} then", self.expr(c));
                    self.stmts(a, &format!("{indent}  "), out);
                    if b.is_empty() {
                        let _ = writeln!(out, "{indent}end if;");
                    } else {
                        let _ = writeln!(out, "{indent}else");
                        self.stmts(b, &format!("{indent}  "), out);
                        let _ = writeln!(out, "{indent}end if;");
                    }
                }
            }
        }
    }

    fn action_code(&self, a: usize, indent: &str, out: &mut String) {
        let text = self.m.actions[a].text.trim();
        let _ = writeln!(out, "{indent}{a} := counted({a});", a = self.act(a));
        if let Some(code) = self.fx.actions.get(text) {
            self.stmts(code, indent, out);
        }
    }

    fn guard(&self, text: &str) -> String {
        match self.m.guard(text) {
            Guard::Always => "true".to_string(),
            Guard::Never => "false".to_string(),
            Guard::Condition(c) => self.cond(c),
            Guard::Code(code) => self.expr(&self.fx.guards[&code]),
        }
    }

    fn holds(&self, guards: &[String], segment: &Segment) -> String {
        let mut parts: Vec<String> = guards.iter().filter(|g| self.m.guard(g) != Guard::Always).map(|g| self.guard(g)).collect();
        if let Next::Choice { branches, .. } = &segment.next {
            let any: Vec<String> = branches.iter().map(|b| self.holds(&b.guards, &b.segment)).collect();
            if !any.iter().any(|a| a == "true") {
                parts.push(format!("({})", any.join(" or ")));
            }
        }
        match parts.len() {
            0 => "true".to_string(),
            1 => parts.remove(0),
            _ => parts.iter().map(|p| if p.starts_with('(') { p.clone() } else { format!("({p})") }).collect::<Vec<_>>().join(" and "),
        }
    }

    fn never(&self, guards: &[String]) -> bool {
        guards.iter().any(|g| self.m.guard(g) == Guard::Never)
    }

    fn transition_actions(&self, transitions: &[usize], indent: &str, out: &mut String) {
        for &t in transitions {
            if let Some(a) = self.m.transitions[t].action {
                let _ = writeln!(out, "{indent}-- {}: {}", comment(&self.m.transitions[t].label), comment(&self.m.actions[a].text));
                self.action_code(a, indent, out);
            }
        }
    }

    fn entry(&self, ops: &[EntryOp], indent: &str, out: &mut String) {
        for op in ops {
            match op {
                EntryOp::Enter(s) => {
                    let _ = writeln!(out, "{indent}enter_one({s}); -- {}", comment(&self.m.states[*s].path));
                }
                EntryOp::Action(t) => self.transition_actions(&[*t], indent, out),
                EntryOp::History { pseudo, default } => {
                    let inner = format!("{indent}  ");
                    match self.m.histories().into_iter().find(|x| x.0 == *pseudo) {
                        Some((p, true, _, (lo, hi))) => {
                            let _ = writeln!(out, "{indent}if has_{p} then -- deep history {}\n{indent}  for k in {lo} to {hi} loop\n{indent}    if deep_{p}(k - {lo}) then\n{indent}      enter_one(k);\n{indent}    end if;\n{indent}  end loop;\n{indent}else", comment(&self.m.states[p].path));
                            self.entry(default, &inner, out);
                            let _ = writeln!(out, "{indent}end if;");
                        }
                        Some((p, false, _, _)) => {
                            let _ = writeln!(out, "{indent}if hist_{p} /= NO_STATE then -- shallow history {}\n{indent}  enter_default(hist_{p});\n{indent}else", comment(&self.m.states[p].path));
                            self.entry(default, &inner, out);
                            let _ = writeln!(out, "{indent}end if;");
                        }
                        None => self.entry(default, indent, out),
                    }
                }
            }
        }
    }

    fn segment(&self, segment: &Segment, indent: &str, out: &mut String) {
        for &(lo, hi) in &segment.exit {
            let _ = writeln!(out, "{indent}exit_range({lo}, {hi});");
        }
        self.transition_actions(&segment.transitions, indent, out);
        match &segment.next {
            Next::Enter(ops) => self.entry(ops, indent, out),
            Next::Terminate => {
                let _ = writeln!(out, "{indent}-- terminate: no exit action, nothing active any more\n{indent}active := (others => false);\n{indent}terminated := true;");
            }
            Next::Choice { pseudo, branches } => {
                let _ = writeln!(out, "{indent}-- choice {}: the first branch that holds now, else the first", comment(&self.m.states[*pseudo].path));
                if branches.len() == 1 {
                    self.segment(&branches[0].segment, indent, out);
                    return;
                }
                for (n, b) in branches.iter().enumerate() {
                    let _ = writeln!(out, "{indent}{} {} then", if n == 0 { "if" } else { "elsif" }, self.holds(&b.guards, &b.segment));
                    self.segment(&b.segment, &format!("{indent}  "), out);
                }
                let _ = writeln!(out, "{indent}else");
                self.segment(&branches[0].segment, &format!("{indent}  "), out);
                let _ = writeln!(out, "{indent}end if;");
            }
        }
    }

    fn sources_active(&self, c: usize) -> String {
        self.m.compounds[c].compound.sources.iter().map(|s| format!("active({s})")).collect::<Vec<_>>().join(" and ")
    }

    /// The transitions a trigger fires, chosen first, then fired.
    fn dispatch(&self, trigger: Trigger, order: &[usize], indent: &str, out: &mut String) -> bool {
        let live: Vec<usize> = order.iter().copied().filter(|&c| self.m.compounds[c].compound.alternatives.iter().any(|a| !self.never(&a.guards))).collect();
        if live.is_empty() {
            let _ = writeln!(out, "{indent}null; -- every transition it fires has the guard false");
            return false;
        }
        let mut choose = String::new();
        for (slot, &c) in live.iter().enumerate() {
            let compound = &self.m.compounds[c].compound;
            let mut enabled = self.sources_active(c);
            if let Trigger::Timer(tm) = trigger {
                let ticks = (self.ticks)(self.m.timers[tm].micros);
                enabled.push_str(&format!(" and (in_state({}) >= to_unsigned({ticks}, 32))", self.m.transitions[compound.head].source));
            }
            let _ = writeln!(choose, "{indent}if {enabled} then");
            let alternatives: Vec<(usize, &Alternative)> = compound.alternatives.iter().enumerate().filter(|(_, a)| !self.never(&a.guards)).collect();
            let mut open = false;
            for (n, (a, alt)) in alternatives.iter().enumerate() {
                let cond = self.holds(&alt.guards, &alt.segment);
                if cond == "true" {
                    if n == 0 {
                        let _ = writeln!(choose, "{indent}  alt_{slot} := {};", a + 1);
                    } else {
                        let _ = writeln!(choose, "{indent}  else\n{indent}    alt_{slot} := {};", a + 1);
                    }
                    break;
                }
                let _ = writeln!(choose, "{indent}  {} {cond} then\n{indent}    alt_{slot} := {};", if n == 0 { "if" } else { "elsif" }, a + 1);
                open = true;
            }
            if open {
                let _ = writeln!(choose, "{indent}  end if;");
            }
            let _ = writeln!(choose, "{indent}end if;");
        }
        out.push_str(&choose);
        for (slot, &c) in live.iter().enumerate() {
            let _ = writeln!(out, "{indent}if alt_{slot} /= 0 and {} then\n{indent}  fire_{c}(alt_{slot});\n{indent}end if;", self.sources_active(c));
        }
        true
    }
}

fn symbol(op: Bin) -> &'static str {
    match op {
        Bin::Lt => "<",
        Bin::Le => "<=",
        Bin::Gt => ">",
        Bin::Ge => ">=",
        Bin::Eq => "=",
        _ => "/=",
    }
}

/// The phases of a step, by number.
pub struct Phases {
    pub start: usize,
    pub equations: usize,
    pub events: Option<usize>,
    /// Each trigger that is not an event, and its phase.
    pub triggers: Vec<(Trigger, usize)>,
    pub activities: usize,
    pub finish: usize,
}

pub fn phases(m: &MachinePlan) -> Phases {
    let start = 1;
    let equations = 2;
    let mut next = equations + m.program().equations.len();
    let events = if m.events.is_empty() {
        None
    } else {
        next += 1;
        Some(next - 1)
    };
    let mut triggers = Vec::new();
    for (trigger, _) in &m.dispatch {
        if !matches!(trigger, Trigger::Event(_)) {
            triggers.push((*trigger, next));
            next += 1;
        }
    }
    Phases { start, equations, events, triggers, activities: next, finish: next + 1 }
}

fn port_name(prefix: &str, ident: &str) -> String {
    name(&format!("{prefix}_{ident}"))
}

/// The entity of one machine.
pub fn core(plan: &Plan, m: &MachinePlan, fx: &MachineFixed) -> String {
    let period = fx.period_us;
    let v = V { m, fx, ticks: Box::new(move |us| super::reference::ticks(us, period)) };
    let ent = entity(plan, m);
    let n = m.states.len();
    let program = m.program();
    let ph = phases(m);
    let mut out = banner(plan, &format!("state_machine \"{}\", computed by the programmable logic.", comment(&m.name)));
    let _ = writeln!(out, "-- Fixed point at a period of {period} us (the timers and the blocks' gains are those of it).\n-- States, by index:");
    for (k, s) in m.states.iter().enumerate() {
        let pseudo = m.machine.states[k].pseudo.map(|p| format!(" (pseudo-state: {p:?}, never active)")).unwrap_or_default();
        let _ = writeln!(out, "--   {k}: {}{}", comment(&s.path), comment(&pseudo));
    }
    let _ = writeln!(out, "library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\nuse work.arclang_fx_pkg.all;\n\nentity {ent} is\n  port (");
    let mut ports = vec![
        "    clk : in std_logic".to_string(),
        "    rst : in std_logic -- synchronous: back to init()".to_string(),
        "    step : in std_logic -- one step, taken while ready".to_string(),
        "    ready : out std_logic -- waiting for a step".to_string(),
        "    done : out std_logic -- one clock: the outputs are those of the step".to_string(),
        "    cycles : out unsigned(15 downto 0) -- the clocks the last step took".to_string(),
    ];
    if !m.events.is_empty() {
        ports.push("    ev_count : in unsigned(4 downto 0) -- the events of the step, at most 16".to_string());
        ports.push(format!("    ev_queue : in std_logic_vector({} downto 0) -- event k in bits 8k+7..8k, in the order they arrived", QUEUE * 8 - 1));
    }
    for c in &m.conditions {
        ports.push(format!("    {} : in std_logic -- condition \"{}\"", port_name("i", &c.ident), comment(&c.text)));
    }
    for (i, var) in program.inputs() {
        let ty = if fx.vars[i].kind == Kind::Bool { "std_logic" } else { "signed(31 downto 0)" };
        ports.push(format!("    {} : in {ty} -- in variable \"{}\" {}", port_name("i", &m.variables[i].ident), comment(&var.name), fx.vars[i].kind.label()));
    }
    for s in &m.states {
        ports.push(format!("    {} : out std_logic -- state {}", port_name("o", &s.ident), comment(&s.path)));
    }
    for a in &m.actions {
        ports.push(format!("    {} : out unsigned(7 downto 0) -- action \"{}\": times run", port_name("o", &a.ident), comment(&a.text)));
    }
    for (i, var) in program.variables.iter().enumerate() {
        let ty = if fx.vars[i].kind == Kind::Bool { "std_logic" } else { "signed(31 downto 0)" };
        ports.push(format!("    {} : out {ty} -- variable \"{}\" {}", port_name("o", &m.variables[i].ident), comment(&var.name), fx.vars[i].kind.label()));
    }
    for b in &m.budgets {
        ports.push(format!("    {} : out std_logic -- budget {} of {}", port_name("o", &b.ident), comment(&b.written), comment(&b.label)));
    }
    for (k, p) in ports.iter().enumerate() {
        let (decl, note) = p.split_once(" -- ").unwrap_or((p, ""));
        let sep = if k + 1 == ports.len() { "" } else { ";" };
        let _ = writeln!(out, "{decl}{sep}{}", if note.is_empty() { String::new() } else { format!(" -- {note}") });
    }
    let _ = writeln!(out, "  );\nend entity;\n\narchitecture rtl of {ent} is\nbegin\n  machine : process (clk)\n    constant NO_STATE : natural := 65535;");
    let histories = m.histories();
    let shallow = histories.iter().any(|h| !h.1);
    let parents: Vec<String> = m.states.iter().map(|s| s.parent.unwrap_or(0).to_string()).collect();
    let _ = writeln!(out, "    -- the parent of each state (a top-level state: 0, never read)\n    constant parent_tab : nat_array(0 to {}) := ({});", n - 1, if n == 1 { format!("0 => {}", parents[0]) } else { parents.join(", ") });
    if shallow {
        let last: Vec<String> = m.machine.states.iter().map(|s| s.last.to_string()).collect();
        let starts: Vec<String> = (0..n)
            .map(|k| {
                let node = &m.machine.states[k];
                let first = match node.parent {
                    Some(p) => m.machine.states[p].regions[node.region].initial,
                    None => m.machine.top_regions[node.region].initial,
                };
                (if first == Some(k) { "true" } else { "false" }).to_string()
            })
            .collect();
        let one = |v: Vec<String>| if n == 1 { format!("0 => {}", v[0]) } else { v.join(", ") };
        let _ = writeln!(out, "    constant last_tab : nat_array(0 to {}) := ({});\n    constant starts_tab : bool_array(0 to {}) := ({});", n - 1, one(last), n - 1, one(starts));
    }
    // The state of the machine.
    let _ = writeln!(out, "    variable ph : natural range 0 to {};\n    variable count : unsigned(15 downto 0);\n    variable started : boolean;\n    variable active : bool_array(0 to {});\n    variable in_state : u32_array(0 to {});", ph.finish, n - 1, n - 1);
    if m.terminates() {
        let _ = writeln!(out, "    variable terminated : boolean;");
    } else {
        let _ = writeln!(out, "    constant terminated : boolean := false;");
    }
    for (h, deep, _, (lo, hi)) in &histories {
        if *deep {
            let _ = writeln!(out, "    variable has_{h} : boolean;\n    variable deep_{h} : bool_array(0 to {});", hi - lo);
        } else {
            let _ = writeln!(out, "    variable hist_{h} : natural range 0 to 65535;");
        }
    }
    if !m.events.is_empty() {
        let _ = writeln!(out, "    variable q_count : natural range 0 to {QUEUE};\n    variable q_ev : nat_array(0 to {});\n    variable k_ev : natural range 0 to {QUEUE};", QUEUE - 1);
    }
    for c in 0..m.conditions.len() {
        let _ = writeln!(out, "    variable {} : boolean;", v.cond(c));
    }
    for (i, var) in program.variables.iter().enumerate() {
        let _ = writeln!(out, "    variable {} : {}; -- \"{}\" {}", v.var(i), vtype(fx.vars[i].kind), comment(&var.name), fx.vars[i].kind.label());
    }
    for a in 0..m.actions.len() {
        let _ = writeln!(out, "    variable {} : count8;", v.act(a));
    }
    for (b, block) in fx.blocks.iter().enumerate() {
        for (field, kind, _, _) in &block.fields {
            let _ = writeln!(out, "    variable blk{b}_{} : {}; -- {} {}", field.name(), vtype(*kind), block_kind(block.kind), kind.label());
        }
        for (t, kind) in &block.temps {
            let _ = writeln!(out, "    variable b{b}_{t} : {};", vtype(*kind));
        }
    }
    // Procedures, as the C's functions.
    let actions_proc = |title: &str, pick: &dyn Fn(&super::plan::StatePlan) -> &Vec<usize>, out: &mut String| {
        let _ = writeln!(out, "\n    procedure {title}(s : natural) is\n    begin\n      case s is");
        for (k, s) in m.states.iter().enumerate() {
            let acts = pick(s);
            if acts.is_empty() {
                continue;
            }
            let _ = writeln!(out, "        when {k} => -- {}", comment(&s.path));
            for &a in acts {
                v.action_code(a, "          ", out);
            }
        }
        let _ = writeln!(out, "        when others => null;\n      end case;\n    end procedure;");
    };
    actions_proc("entry_actions", &|s| &s.entry, &mut out);
    let _ = writeln!(out, "\n    procedure enter_one(s : natural) is\n    begin\n      active(s) := true;\n      in_state(s) := (others => '0');\n      entry_actions(s);\n    end procedure;");
    if shallow {
        let _ = writeln!(out, "\n    -- Enter s and the initial states of the regions under it, in the order of the states.\n    procedure enter_default(s : natural) is\n    begin\n      enter_one(s);\n      for k in 0 to {} loop\n        if k > s and k <= last_tab(s) and starts_tab(k) and active(parent_tab(k)) then\n          enter_one(k);\n        end if;\n      end loop;\n    end procedure;", n - 1);
    }
    if !m.compounds.is_empty() {
        actions_proc("exit_actions", &|s| &s.exit, &mut out);
        let deeps = histories.iter().any(|h| h.1);
        let _ = writeln!(out, "\n    -- Exit the active states of lo..hi, the last first; the history of a state exited is kept first.\n    procedure exit_range(lo, hi : natural) is{}{}\n    begin", if deeps { "\n      variable any : boolean;" } else { "" }, if shallow { "\n      variable found : boolean;" } else { "" });
        for &(p, deep, owner, (lo, hi)) in &histories {
            let low = if owner == 0 { String::new() } else { format!("lo <= {owner} and ") };
            let _ = writeln!(out, "      if {low}{owner} <= hi and active({owner}) then");
            if deep {
                let _ = writeln!(out, "        any := false;\n        for k in {lo} to {hi} loop\n          if active(k) then\n            any := true;\n          end if;\n        end loop;\n        if any then\n          for k in {lo} to {hi} loop\n            deep_{p}(k - {lo}) := active(k);\n          end loop;\n          has_{p} := true;\n        end if;");
            } else {
                let _ = writeln!(out, "        found := false;\n        for k in {lo} to {hi} loop\n          if not found and active(k) and parent_tab(k) = {owner} then\n            hist_{p} := k;\n            found := true;\n          end if;\n        end loop;");
            }
            let _ = writeln!(out, "      end if;");
        }
        let _ = writeln!(out, "      for k in {} downto 0 loop\n        if k >= lo and k <= hi and active(k) then\n          active(k) := false;\n          exit_actions(k);\n        end if;\n      end loop;\n    end procedure;", n - 1);
    }
    let _ = writeln!(out, "\n    -- The start: the initial state of every top-level region, down to the leaves.\n    procedure start is\n    begin");
    let mut body = String::new();
    for &top in &m.machine.tops {
        v.entry(&m.machine.default_entry(top), "      ", &mut body);
    }
    out.push_str(if body.is_empty() { "      null;\n" } else { &body });
    let _ = writeln!(out, "    end procedure;");
    for (c, cp) in m.compounds.iter().enumerate() {
        let compound = &cp.compound;
        let head = &m.transitions[compound.head];
        let ends = format!("{} -> {}", m.states[head.source].path, m.states[head.target].path);
        let title = if head.label.contains("->") { ends } else { format!("{} ({ends})", head.label) };
        let _ = writeln!(out, "\n    -- transition {}\n    procedure fire_{c}(alternative : natural) is\n    begin", comment(&title));
        let live: Vec<(usize, &Alternative)> = compound.alternatives.iter().enumerate().filter(|(_, a)| !v.never(&a.guards)).collect();
        let mut body = String::new();
        if live.len() == 1 {
            v.segment(&live[0].1.segment, "      ", &mut body);
        } else {
            let _ = writeln!(body, "      case alternative is");
            for (a, alt) in &live {
                let _ = writeln!(body, "        when {} =>", a + 1);
                let mut inner = String::new();
                v.segment(&alt.segment, "          ", &mut inner);
                body.push_str(if inner.is_empty() { "          null;\n" } else { &inner });
            }
            let _ = writeln!(body, "        when others => null;\n      end case;");
        }
        out.push_str(if body.is_empty() { "      null;\n" } else { &body });
        let _ = writeln!(out, "    end procedure;");
    }
    // A procedure per trigger: the events', and those of the phases.
    for (trigger, order) in &m.dispatch {
        let title = match trigger {
            Trigger::Event(e) => format!("on_{e}"),
            Trigger::Timer(tm) => format!("timer_{tm}"),
            Trigger::Completion => "completion".to_string(),
        };
        let what = match trigger {
            Trigger::Event(e) => format!("event \"{}\"", comment(&m.events[*e].text)),
            Trigger::Timer(tm) => format!("timed: {}", comment(&m.timers[*tm].label)),
            Trigger::Completion => "completion transitions".to_string(),
        };
        let live = order.iter().filter(|&&c| m.compounds[c].compound.alternatives.iter().any(|a| !v.never(&a.guards))).count();
        let _ = writeln!(out, "\n    -- {what}: its transitions\n    procedure {title} is");
        for slot in 0..live {
            let _ = writeln!(out, "      variable alt_{slot} : natural range 0 to 255 := 0;");
        }
        let _ = writeln!(out, "    begin");
        let mut body = String::new();
        v.dispatch(*trigger, order, "      ", &mut body);
        out.push_str(&body);
        let _ = writeln!(out, "    end procedure;");
    }
    // The process.
    let _ = writeln!(out, "\n  begin\n    if rising_edge(clk) then\n      done <= '0';\n      if rst = '1' then");
    let mut init = String::new();
    let _ = writeln!(init, "ph := 0;\ncount := (others => '0');\nstarted := false;\nactive := (others => false);\nin_state := (others => (others => '0'));");
    if m.terminates() {
        let _ = writeln!(init, "terminated := false;");
    }
    for (h, deep, _, _) in &histories {
        if *deep {
            let _ = writeln!(init, "has_{h} := false;\ndeep_{h} := (others => false);");
        } else {
            let _ = writeln!(init, "hist_{h} := NO_STATE;");
        }
    }
    if !m.events.is_empty() {
        let _ = writeln!(init, "q_count := 0;\nq_ev := (others => 0);\nk_ev := 0;");
    }
    for c in 0..m.conditions.len() {
        let _ = writeln!(init, "{} := false;", v.cond(c));
    }
    for (i, var) in fx.vars.iter().enumerate() {
        let _ = writeln!(init, "{} := {};", v.var(i), lit(var.kind, var.initial));
    }
    for a in 0..m.actions.len() {
        let _ = writeln!(init, "{} := (others => '0');", v.act(a));
    }
    for (b, block) in fx.blocks.iter().enumerate() {
        for (field, kind, raw, _) in &block.fields {
            let _ = writeln!(init, "blk{b}_{} := {};", field.name(), lit(*kind, *raw));
        }
        for (t, kind) in &block.temps {
            let _ = writeln!(init, "b{b}_{t} := {};", lit(*kind, 0));
        }
    }
    let _ = writeln!(init, "ready <= '1';\ncycles <= (others => '0');");
    for s in &m.states {
        let _ = writeln!(init, "{} <= '0';", port_name("o", &s.ident));
    }
    for a in &m.actions {
        let _ = writeln!(init, "{} <= (others => '0');", port_name("o", &a.ident));
    }
    for (i, var) in fx.vars.iter().enumerate() {
        let value = if var.kind == Kind::Bool { "'0'".to_string() } else { "(others => '0')".to_string() };
        let _ = writeln!(init, "{} <= {value};", port_name("o", &m.variables[i].ident));
    }
    for b in &m.budgets {
        let _ = writeln!(init, "{} <= '0';", port_name("o", &b.ident));
    }
    for line in init.lines() {
        let _ = writeln!(out, "        {line}");
    }
    let _ = writeln!(out, "      else\n        case ph is\n          when 0 =>\n            if step = '1' then\n              -- the inputs of the step, latched");
    if !m.events.is_empty() {
        let _ = writeln!(out, "              if to_integer(ev_count) > {QUEUE} then\n                q_count := {QUEUE};\n              else\n                q_count := to_integer(ev_count);\n              end if;\n              for k in 0 to {} loop\n                q_ev(k) := to_integer(unsigned(ev_queue(8 * k + 7 downto 8 * k)));\n              end loop;\n              k_ev := 0;", QUEUE - 1);
    }
    for c in &m.conditions {
        let _ = writeln!(out, "              l_{} := {} = '1';", name(&c.ident), port_name("i", &c.ident));
    }
    for (i, _) in program.inputs() {
        let port = port_name("i", &m.variables[i].ident);
        let value = if fx.vars[i].kind == Kind::Bool { format!("{port} = '1'") } else { port };
        let _ = writeln!(out, "              {} := {value};", v.var(i));
    }
    for a in 0..m.actions.len() {
        let _ = writeln!(out, "              {} := (others => '0');", v.act(a));
    }
    let after_start = |indent: &str| format!("{indent}if terminated then\n{indent}  ph := {};\n{indent}else\n{indent}  ph := {};\n{indent}end if;", ph.finish, ph.equations);
    let _ = writeln!(out, "              count := to_unsigned(1, 16);\n              ready <= '0';\n              if not started then\n                started := true;\n                ph := {};\n              else\n{}\n              end if;\n            end if;", ph.start, after_start("                "));
    let _ = writeln!(out, "          when {} => -- the initial states\n            start;\n{}", ph.start, after_start("            "));
    for (k, e) in program.equations.iter().enumerate() {
        let _ = writeln!(out, "          when {} => -- equation \"{}\"", ph.equations + k, comment(&e.text));
        v.stmts(&fx.equations[k], "            ", &mut out);
        let _ = writeln!(out, "            ph := {};", ph.equations + k + 1);
    }
    if let Some(p) = ph.events {
        let _ = writeln!(out, "          when {p} => -- the events, one a clock, in the order they arrived\n            if k_ev < q_count then\n              case q_ev(k_ev) is");
        for (trigger, _) in &m.dispatch {
            if let Trigger::Event(e) = trigger {
                let _ = writeln!(out, "                when {e} => on_{e}; -- \"{}\"", comment(&m.events[*e].text));
            }
        }
        let _ = writeln!(out, "                when others => null;\n              end case;\n              k_ev := k_ev + 1;\n            else\n              ph := {};\n            end if;", p + 1);
    }
    for (trigger, p) in &ph.triggers {
        let call = match trigger {
            Trigger::Timer(tm) => format!("timer_{tm}; -- {}", comment(&m.timers[*tm].label)),
            _ => "completion;".to_string(),
        };
        let _ = writeln!(out, "          when {p} =>\n            {call}\n            ph := {};", p + 1);
    }
    let _ = writeln!(out, "          when {} => -- the do activities of the active states, the time in state", ph.activities);
    for k in 0..n {
        if m.states[k].activity.is_empty() {
            continue;
        }
        let _ = writeln!(out, "            if active({k}) then");
        for &a in &m.states[k].activity {
            v.action_code(a, "              ", &mut out);
        }
        let _ = writeln!(out, "            end if;");
    }
    let _ = writeln!(out, "            for k in 0 to {} loop\n              if active(k) and in_state(k) /= x\"FFFFFFFF\" then\n                in_state(k) := in_state(k) + 1;\n              end if;\n            end loop;\n            ph := {};", n - 1, ph.finish);
    let _ = writeln!(out, "          when others => -- the outputs of the step");
    for (k, s) in m.states.iter().enumerate() {
        let _ = writeln!(out, "            {} <= b2l(active({k}));", port_name("o", &s.ident));
    }
    for (a, act) in m.actions.iter().enumerate() {
        let _ = writeln!(out, "            {} <= {};", port_name("o", &act.ident), v.act(a));
    }
    for (i, var) in fx.vars.iter().enumerate() {
        let value = if var.kind == Kind::Bool { format!("b2l({})", v.var(i)) } else { v.var(i) };
        let _ = writeln!(out, "            {} <= {value};", port_name("o", &m.variables[i].ident));
    }
    for b in &m.budgets {
        let ticks = super::reference::ticks(b.micros, period);
        let _ = writeln!(out, "            {} <= b2l(active({s}) and in_state({s}) > to_unsigned({ticks}, 32)); -- budget {}", port_name("o", &b.ident), comment(&b.written), s = b.source);
    }
    let _ = writeln!(out, "            cycles <= count;\n            done <= '1';\n            ready <= '1';\n            ph := 0;\n        end case;\n        if ph /= 0 and count /= x\"FFFF\" then\n          count := count + 1;\n        end if;\n      end if;\n    end if;\n  end process;\nend architecture;");
    out
}

fn block_kind(kind: BlockKind) -> &'static str {
    match kind {
        BlockKind::Delay => "delay",
        BlockKind::Integrator { .. } => "integrator",
        BlockKind::Pid { .. } => "pid",
    }
}

/// The Wishbone wrapper: the registers of the map around the entity.
pub fn wrapper(plan: &Plan, m: &MachinePlan, fx: &MachineFixed, map: &Map) -> String {
    let ent = entity(plan, m);
    let aw = map.address_bits();
    let mut out = banner(plan, &format!("The registers of state_machine \"{}\" on a Wishbone bus (B4 classic, 32-bit, word addressed, as LiteX's wishbone.Interface).", comment(&m.name)));
    let _ = writeln!(out, "-- Registers (word index: name):");
    for r in &map.registers {
        let _ = writeln!(out, "--   {:3}: {} ({}) {}", r.index, r.name, if r.write { "rw" } else { "ro" }, comment(&r.description));
    }
    let _ = writeln!(
        out,
        "library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\nuse work.arclang_fx_pkg.all;\n\nentity {ent}_wb is\n  port (\n    clk      : in  std_logic;\n    rst      : in  std_logic;\n    wb_adr   : in  std_logic_vector({} downto 0);\n    wb_dat_w : in  std_logic_vector(31 downto 0);\n    wb_dat_r : out std_logic_vector(31 downto 0);\n    wb_sel   : in  std_logic_vector(3 downto 0);\n    wb_cyc   : in  std_logic;\n    wb_stb   : in  std_logic;\n    wb_we    : in  std_logic;\n    wb_ack   : out std_logic;\n    wb_err   : out std_logic;\n    irq      : out std_logic -- high while DONE\n  );\nend entity;\n\narchitecture rtl of {ent}_wb is",
        aw - 1
    );
    let program = m.program();
    let mut sigs = vec!["  signal core_rst, core_step, core_ready, core_done, ack, done_flag : std_logic := '0';".to_string(), "  signal core_cycles : unsigned(15 downto 0);".to_string()];
    if !m.events.is_empty() {
        sigs.push("  signal ev_count : unsigned(4 downto 0) := (others => '0');".to_string());
        sigs.push(format!("  signal ev_queue : std_logic_vector({} downto 0) := (others => '0');", QUEUE * 8 - 1));
    }
    for n in 0..super::regmap::words(m.conditions.len()) {
        sigs.push(format!("  signal cond{n} : std_logic_vector(31 downto 0) := (others => '0');"));
    }
    for (i, _) in program.inputs() {
        sigs.push(format!("  signal in_{} : std_logic_vector(31 downto 0) := (others => '0');", name(&m.variables[i].ident)));
    }
    for s in &m.states {
        sigs.push(format!("  signal {} : std_logic;", port_name("o", &s.ident)));
    }
    for a in &m.actions {
        sigs.push(format!("  signal {} : unsigned(7 downto 0);", port_name("o", &a.ident)));
    }
    for (i, var) in fx.vars.iter().enumerate() {
        let ty = if var.kind == Kind::Bool { "std_logic" } else { "signed(31 downto 0)" };
        sigs.push(format!("  signal {} : {ty};", port_name("o", &m.variables[i].ident)));
    }
    for b in &m.budgets {
        sigs.push(format!("  signal {} : std_logic;", port_name("o", &b.ident)));
    }
    for s in sigs {
        let _ = writeln!(out, "{s}");
    }
    let _ = writeln!(out, "begin\n  core : entity work.{ent}\n    port map (\n      clk => clk,\n      rst => core_rst,\n      step => core_step,\n      ready => core_ready,\n      done => core_done,\n      cycles => core_cycles,");
    let mut maps: Vec<String> = Vec::new();
    if !m.events.is_empty() {
        maps.push("ev_count => ev_count".to_string());
        maps.push("ev_queue => ev_queue".to_string());
    }
    for (c, cond) in m.conditions.iter().enumerate() {
        maps.push(format!("{} => cond{}({})", port_name("i", &cond.ident), c / 32, c % 32));
    }
    for (i, _) in program.inputs() {
        let port = port_name("i", &m.variables[i].ident);
        let reg = format!("in_{}", name(&m.variables[i].ident));
        maps.push(if fx.vars[i].kind == Kind::Bool { format!("{port} => {reg}(0)") } else { format!("{port} => signed({reg})") });
    }
    for s in &m.states {
        maps.push(format!("{p} => {p}", p = port_name("o", &s.ident)));
    }
    for a in &m.actions {
        maps.push(format!("{p} => {p}", p = port_name("o", &a.ident)));
    }
    for i in 0..fx.vars.len() {
        maps.push(format!("{p} => {p}", p = port_name("o", &m.variables[i].ident)));
    }
    for b in &m.budgets {
        maps.push(format!("{p} => {p}", p = port_name("o", &b.ident)));
    }
    let _ = writeln!(out, "{}\n    );", maps.iter().map(|x| format!("      {x}")).collect::<Vec<_>>().join(",\n"));
    let _ = writeln!(out, "  wb_ack <= ack;\n  wb_err <= '0';\n  irq <= done_flag;\n\n  registers : process (clk)\n    variable a : natural;\n    variable r : std_logic_vector(31 downto 0);\n  begin\n    if rising_edge(clk) then\n      core_step <= '0';\n      core_rst <= rst;\n      ack <= '0';\n      if core_done = '1' then\n        done_flag <= '1';\n      end if;\n      if rst = '1' then\n        done_flag <= '0';");
    if !m.events.is_empty() {
        let _ = writeln!(out, "        ev_count <= (others => '0');\n        ev_queue <= (others => '0');");
    }
    for n in 0..super::regmap::words(m.conditions.len()) {
        let _ = writeln!(out, "        cond{n} <= (others => '0');");
    }
    for (i, _) in program.inputs() {
        let _ = writeln!(out, "        in_{} <= (others => '0');", name(&m.variables[i].ident));
    }
    let _ = writeln!(out, "      elsif wb_cyc = '1' and wb_stb = '1' and ack = '0' then\n        ack <= '1';\n        a := to_integer(unsigned(wb_adr));\n        if wb_we = '1' then\n          case a is");
    for reg in map.registers.iter().filter(|r| r.write) {
        let target = match reg.reg {
            Reg::Ctrl => "if wb_dat_w(1) = '1' then\n              core_rst <= '1';\n              done_flag <= '0';\n            elsif wb_dat_w(0) = '1' then\n              core_step <= '1';\n              done_flag <= '0';\n            end if;".to_string(),
            Reg::EvCount => "ev_count <= unsigned(wb_dat_w(4 downto 0));".to_string(),
            Reg::EvQueue(k) => format!("ev_queue({} downto {}) <= wb_dat_w(7 downto 0);", 8 * k + 7, 8 * k),
            Reg::Cond(n) => format!("cond{n} <= wb_dat_w;"),
            Reg::In(i) => format!("in_{} <= wb_dat_w;", name(&m.variables[i].ident)),
            _ => "null;".to_string(),
        };
        let _ = writeln!(out, "            when {} => -- {}\n            {target}", reg.index, reg.name);
    }
    let _ = writeln!(out, "            when others => null;\n          end case;\n        end if;\n        r := (others => '0');\n        case a is");
    for reg in &map.registers {
        let value = match reg.reg {
            Reg::Ctrl => continue,
            Reg::Status => "r(0) := core_ready;\n            r(1) := done_flag;".to_string(),
            Reg::Cycles => "r(15 downto 0) := std_logic_vector(core_cycles);".to_string(),
            Reg::EvCount => "r(4 downto 0) := std_logic_vector(ev_count);".to_string(),
            Reg::EvQueue(k) => format!("r(7 downto 0) := ev_queue({} downto {});", 8 * k + 7, 8 * k),
            Reg::Cond(n) => format!("r := cond{n};"),
            Reg::In(i) => format!("r := in_{};", name(&m.variables[i].ident)),
            Reg::State(w) => m.states.iter().enumerate().skip(32 * w).take(32).map(|(k, s)| format!("r({}) := {};", k - 32 * w, port_name("o", &s.ident))).collect::<Vec<_>>().join("\n            "),
            Reg::Action(a) => format!("r(7 downto 0) := std_logic_vector({});", port_name("o", &m.actions[a].ident)),
            Reg::Var(i) => {
                let p = port_name("o", &m.variables[i].ident);
                if fx.vars[i].kind == Kind::Bool {
                    format!("r(0) := {p};")
                } else {
                    format!("r := std_logic_vector({p});")
                }
            }
            Reg::Budget(w) => m.budgets.iter().enumerate().skip(32 * w).take(32).map(|(k, b)| format!("r({}) := {};", k - 32 * w, port_name("o", &b.ident))).collect::<Vec<_>>().join("\n            "),
        };
        let _ = writeln!(out, "          when {} => -- {}\n            {value}", reg.index, reg.name);
    }
    let _ = writeln!(out, "          when others => null;\n        end case;\n        wb_dat_r <= r;\n      end if;\n    end if;\n  end process;\nend architecture;");
    out
}

/// The testbench of `arclang hdl`: it plays a file of bus operations on
/// the wrapper (`W <index> <hex word>`, `G`: a step, its outputs read), and
/// writes the registers read after each step as a line of hex words.
pub fn testbench(plan: &Plan, m: &MachinePlan, map: &Map) -> String {
    let ent = entity(plan, m);
    let aw = map.address_bits();
    let status = map.find(&Reg::Status).expect("status").index;
    let ctrl = map.find(&Reg::Ctrl).expect("ctrl").index;
    let reads: Vec<String> = map.outputs().iter().map(|r| format!("        wb_read({}, d); hwrite(o, d); write(o, ' ');", r.index)).collect();
    let mut out = banner(plan, &format!("The testbench of arclang hdl for state_machine \"{}\": bus operations from a file, the registers after each step to a file.", comment(&m.name)));
    let _ = writeln!(
        out,
        "library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\nuse std.textio.all;\n\nentity {ent}_tb is\n  generic (STIMULUS : string := \"stimulus.txt\"; RESULT : string := \"result.txt\"; TIMEOUT : natural := 100000);\nend entity;\n\narchitecture sim of {ent}_tb is\n  signal clk : std_logic := '0';\n  signal rst : std_logic := '1';\n  signal running : boolean := true;\n  signal wb_adr : std_logic_vector({} downto 0) := (others => '0');\n  signal wb_dat_w, wb_dat_r : std_logic_vector(31 downto 0) := (others => '0');\n  signal wb_sel : std_logic_vector(3 downto 0) := \"1111\";\n  signal wb_cyc, wb_stb, wb_we, wb_ack, wb_err, irq : std_logic := '0';\nbegin\n  clk <= not clk after 10 ns when running else '0';\n\n  dut : entity work.{ent}_wb\n    port map (clk => clk, rst => rst, wb_adr => wb_adr, wb_dat_w => wb_dat_w, wb_dat_r => wb_dat_r, wb_sel => wb_sel,\n              wb_cyc => wb_cyc, wb_stb => wb_stb, wb_we => wb_we, wb_ack => wb_ack, wb_err => wb_err, irq => irq);\n\n  play : process\n    file stimulus_file : text open read_mode is STIMULUS;\n    file result_file : text open write_mode is RESULT;\n    variable l, o : line;\n    variable c : character;\n    variable index : natural;\n    variable d : std_logic_vector(31 downto 0);\n    variable polls : natural;\n\n    procedure wb_write(a : natural; v : std_logic_vector(31 downto 0)) is\n    begin\n      wb_adr <= std_logic_vector(to_unsigned(a, wb_adr'length));\n      wb_dat_w <= v;\n      wb_we <= '1';\n      wb_cyc <= '1';\n      wb_stb <= '1';\n      loop\n        wait until rising_edge(clk);\n        exit when wb_ack = '1';\n      end loop;\n      wb_cyc <= '0';\n      wb_stb <= '0';\n      wb_we <= '0';\n      wait until rising_edge(clk);\n    end procedure;\n\n    procedure wb_read(a : natural; v : out std_logic_vector(31 downto 0)) is\n    begin\n      wb_adr <= std_logic_vector(to_unsigned(a, wb_adr'length));\n      wb_we <= '0';\n      wb_cyc <= '1';\n      wb_stb <= '1';\n      loop\n        wait until rising_edge(clk);\n        exit when wb_ack = '1';\n      end loop;\n      v := wb_dat_r;\n      wb_cyc <= '0';\n      wb_stb <= '0';\n      wait until rising_edge(clk);\n    end procedure;\n  begin\n    rst <= '1';\n    wait until rising_edge(clk);\n    wait until rising_edge(clk);\n    rst <= '0';\n    wait until rising_edge(clk);\n    while not endfile(stimulus_file) loop\n      readline(stimulus_file, l);\n      next when l'length = 0;\n      read(l, c);\n      if c = 'W' then\n        read(l, index);\n        hread(l, d);\n        wb_write(index, d);\n      elsif c = 'G' then\n        wb_write({ctrl}, x\"00000001\");\n        polls := 0;\n        loop\n          wb_read({status}, d);\n          exit when d(1) = '1';\n          polls := polls + 1;\n          if polls > TIMEOUT then\n            write(o, string'(\"error the block never finished the step\"));\n            writeline(result_file, o);\n            running <= false;\n            wait;\n          end if;\n        end loop;\n{}\n        writeline(result_file, o);\n      end if;\n    end loop;\n    running <= false;\n    wait;\n  end process;\nend architecture;",
        aw - 1,
        reads.join("\n")
    );
    out
}

/// Every file of the hardware of a machine, at a period: the package, the
/// entity, the wrapper, the register map (JSON, csr.csv) and the C driver.
pub fn files(plan: &Plan, m: &MachinePlan, fx: &MachineFixed) -> Vec<(String, String)> {
    let map = super::regmap::map(plan, m, fx);
    let ent = entity(plan, m);
    vec![
        ("arclang_fx_pkg.vhd".to_string(), PACKAGE.to_string()),
        (format!("{ent}.vhd"), core(plan, m, fx)),
        (format!("{ent}_wb.vhd"), wrapper(plan, m, fx, &map)),
        (format!("{ent}_regs.json"), super::regmap::json(&map, m, fx)),
        (format!("{ent}_csr.csv"), super::regmap::csv(&map)),
        (format!("{ent}_hw.h"), super::regmap::driver(plan, m, fx, &map)),
    ]
}
